function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000);}
function modal(title,body,wide=false){const d=$('#modal');d.className=wide?'wide':'';d.innerHTML=`<div class="modalhead"><div><span class="eyebrow">AXIOM / ${publicView?'STUDIO':esc(roles[role].dept)}</span><h2>${title}</h2></div><button class="close" data-act="close" aria-label="Close dialog">×</button></div>${body}`;if(!d.open)d.showModal();}
