function enter(r,id){const u=id?users.find(u=>u.id===id):users.find(u=>u.active&&u.roles.includes(r));if(!u?.active||!u.roles.includes(r)){toast('No active user has this role. Assign it in Admin first.');return;}role=r;userId=u.id;customerName=u.name.split(' ')[0];publicView=false;page='overview';query='';activeThread='t1';location.hash=r+'/overview';render();}
