function switcher(){modal('Choose your perspective.',`<p class="muted">Preview an assigned account and workspace. This demonstrates navigation, not secure authentication.</p><div class="role-grid">${Object.entries(roles).map(([id,r])=>{const assigned=users.filter(u=>u.active&&u.roles.includes(id));return `<div class="role-option"><span class="tileicon">${icon(r.icon)}</span><strong>${r.name}</strong><small>${r.dept}</small>${assigned.map(u=>button(esc(u.name)+' ↗','enter',id+'|'+u.id,'small')).join('')||'<small>No active assigned user</small>'}</div>`;}).join('')}</div>`,true);}
function render(){if(publicView){landing();return;}if(!roles[role].pages.some(x=>x[0]===page))page='overview';const r=roles[role];$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><button class="brand" data-act="home"><span class="mark">↗</span>axiom<span class="brand-dot">.</span></button><div class="workspace"><span class="tileicon">${icon(r.icon)}</span><div>${esc(r.dept)}<small>${esc(r.name)}</small></div></div><div class="navlabel">YOUR WORKSPACE</div><nav>${r.pages.map(([id,name])=>`<button class="navitem ${id===page?'active':''}" data-act="go" data-id="${id}">${icon(id==='overview'?r.icon:id==='messages'?'chat':id==='cart'?'cart':id==='appointments'?'calendar':id==='assistant'?'spark':id==='users'?'users':id==='quotes'?'doc':id==='invoices'?'card':'grid')}<span>${name}</span></button>`).join('')}</nav><div class="sidefoot"><div class="rolebox"><span class="eyebrow">TEAM PREVIEW</span><p>${esc(me().name)}</p>${button('Switch workspace ↗','switch','','small')}</div><button class="navitem" data-act="home">${icon('home')}Studio website</button></div></aside><main class="main"><header class="appbar"><div class="crumb"><span>Workspace</span><span>/</span><strong>${esc(r.pages.find(x=>x[0]===page)?.[1])}</strong></div><div class="right"><span class="demo-dot">Interactive demo</span><button class="iconbtn" data-act="notifications" aria-label="Notifications">${icon('bell')}</button><button class="avatar" data-act="profile" aria-label="Your profile">${initial(me().name)}</button><button class="mobile-switch" data-act="switch">Switch role</button></div></header><div class="content">${page==='overview'?overview():pageView()}<footer class="appfooter"><span>AXIOM / ${esc(r.dept)}</span><span>Session demo · Changes reset on reload · No real email or charges</span></footer></div></main></div>`;}
function head(title,sub,action='',label='',id=''){return `<div class="pagehead"><div><span class="eyebrow">${esc(roles[role].dept)}</span><h1>${title}</h1><p>${sub}</p></div>${action?button(label,action,id,'primary'):''}</div>`;}
function stats(items){return `<div class="metrics">${items.map(([label,n,sub],i)=>`<div class="metric"><span class="metriclabel">${label}${icon(['grid','clock','check','spark'][i%4])}</span><strong>${n}</strong><small>${sub||''}</small></div>`).join('')}</div>`;}
