document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(b){e.preventDefault();act(b.dataset.act,b.dataset.id||'');}});
document.addEventListener('submit',e=>{const f=e.target.closest('form[data-form]');if(f){e.preventDefault();submitForm(f,e.submitter);}});
document.addEventListener('change',e=>{if(e.target.matches('[data-search]')){query=e.target.value;render();}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))close();});
function readRoute(){const [r,p]=location.hash.slice(1).split('/');const aliases={employee:'designer'};const key=aliases[r]||r;if(roles[key]){const u=users.find(u=>u.active&&u.roles.includes(key));if(!u){publicView=true;landing();return;}role=key;if(!users.find(u=>u.id===userId)?.roles.includes(key))userId=u.id;publicView=false;page=roles[key].pages.some(x=>x[0]===p)?p:'overview';render();}else{publicView=true;landing();}}
window.addEventListener('popstate',readRoute);
